import { Button } from '@patternfly/react-core/dist/dynamic/components/Button';
import { DatePicker } from '@patternfly/react-core/dist/dynamic/components/DatePicker';
import { Form } from '@patternfly/react-core/dist/dynamic/components/Form';
import { FormGroup } from '@patternfly/react-core/dist/dynamic/components/Form';
import { InputGroup } from '@patternfly/react-core/dist/dynamic/components/InputGroup';
import { InputGroupItem } from '@patternfly/react-core/dist/dynamic/components/InputGroup';
import { Modal } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalBody } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalFooter } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalHeader } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { ModalVariant } from '@patternfly/react-core/dist/dynamic/components/Modal';
import { TimePicker } from '@patternfly/react-core/dist/dynamic/components/TimePicker';
import * as _ from 'lodash-es';
import type { FC, MouseEventHandler } from 'react';
import { useState } from 'react';
import { useTranslation } from 'react-i18next';

import { QueryParams } from '../../../shared/constants/query-params';
import { NumberParam, useQueryParam } from 'use-query-params';
import { TimeRangeParam } from '../utils/utils';

const zeroPad = (number: number) => (number < 10 ? `0${number}` : number);

// Get YYYY-MM-DD date string for a date object
const toISODateString = (date: Date): string =>
  `${date.getFullYear()}-${zeroPad(date.getMonth() + 1)}-${zeroPad(date.getDate())}`;

// Get HH:MM time string for a date object
const toISOTimeString = (date: Date): string =>
  new Intl.DateTimeFormat('en', { hour: 'numeric', minute: 'numeric', hourCycle: 'h23' }).format(
    date,
  );

type CustomTimeRangeModalProps = {
  isOpen: boolean;
  setClosed: () => void;
  timespan?: number;
  endTime?: number;
};

const CustomTimeRangeModal: FC<CustomTimeRangeModalProps> = ({
  isOpen,
  setClosed,
  timespan,
  endTime,
}) => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);
  const [, setEndTimeParam] = useQueryParam(QueryParams.EndTime, NumberParam);
  const [, setTimeRangeParam] = useQueryParam(QueryParams.TimeRange, TimeRangeParam);

  // If a time is already set in Redux, default to that, otherwise default to a time range that
  // covers all of today
  const now = new Date();
  const defaultFrom = endTime && timespan ? new Date(endTime - timespan) : undefined;
  const [fromDate, setFromDate] = useState(toISODateString(defaultFrom ?? now));
  const [fromTime, setFromTime] = useState(defaultFrom ? toISOTimeString(defaultFrom) : '00:00');
  const [toDate, setToDate] = useState(toISODateString(endTime ? new Date(endTime) : now));
  const [toTime, setToTime] = useState(endTime ? toISOTimeString(new Date(endTime)) : '23:59');

  const submit: MouseEventHandler<HTMLButtonElement> = () => {
    const from = Date.parse(`${fromDate} ${fromTime}`);
    const to = Date.parse(`${toDate} ${toTime}`);
    if (_.isInteger(from) && _.isInteger(to)) {
      setEndTimeParam(to);
      setTimeRangeParam(to - from);
      setClosed();
    }
  };

  return (
    <Modal
      isOpen={isOpen}
      position="top"
      title={t('Custom time range')}
      onClose={setClosed}
      variant={ModalVariant.small}
    >
      <ModalHeader title={t('Custom time range')} />
      <ModalBody>
        <Form>
          <FormGroup label={t('From')} isRequired fieldId="custom-time-range-from">
            <InputGroup>
              <InputGroupItem>
                <DatePicker
                  onChange={(event, str) => setFromDate(str)}
                  value={fromDate}
                  appendTo={() => document.body}
                />
              </InputGroupItem>
              <InputGroupItem>
                <TimePicker
                  is24Hour
                  onChange={(event, text) => setFromTime(text)}
                  time={fromTime}
                  menuAppendTo={() => document.body}
                />
              </InputGroupItem>
            </InputGroup>
          </FormGroup>

          <FormGroup label={t('To')} isRequired fieldId="custom-time-range-to">
            <InputGroup>
              <InputGroupItem>
                <DatePicker
                  onChange={(event, str) => setToDate(str)}
                  value={toDate}
                  appendTo={() => document.body}
                />
              </InputGroupItem>
              <InputGroupItem>
                <TimePicker
                  is24Hour
                  onChange={(event, text) => setToTime(text)}
                  time={toTime}
                  menuAppendTo={() => document.body}
                />
              </InputGroupItem>
            </InputGroup>
          </FormGroup>
        </Form>
      </ModalBody>
      <ModalFooter>
        <Button variant="primary" onClick={submit}>
          {t('Save')}
        </Button>
        <Button variant="secondary" onClick={setClosed}>
          {t('Cancel')}
        </Button>
      </ModalFooter>
    </Modal>
  );
};

export default CustomTimeRangeModal;
