import * as _ from 'lodash-es';
import type { FC, PropsWithChildren } from 'react';
import { memo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';

import { Divider } from '@patternfly/react-core/dist/dynamic/components/Divider';
import { PageSection } from '@patternfly/react-core/dist/dynamic/components/Page';
import { Split } from '@patternfly/react-core/dist/dynamic/layouts/Split';
import { SplitItem } from '@patternfly/react-core/dist/dynamic/layouts/Split';
import { Stack } from '@patternfly/react-core/dist/dynamic/layouts/Stack';
import { StackItem } from '@patternfly/react-core/dist/dynamic/layouts/Stack';
import { CombinedDashboardMetadata } from '../../perses-dashboards/hooks/useDashboardsData';
import { DashboardDropdown } from '../../../shared/components/dashboard-dropdown';
import { PollIntervalDropdown, TimespanDropdown } from './time-dropdowns';
import { LegacyDashboardsAllVariableDropdowns } from './legacy-variable-dropdowns';
import { DocumentTitle, ListPageHeader } from '@openshift-console/dynamic-plugin-sdk';

const HeaderTop: FC = memo(() => {
  const { t } = useTranslation(process.env.I18N_NAMESPACE);

  return (
    <ListPageHeader title={t('Dashboards')}>
      <Split hasGutter isWrappable>
        <SplitItem>
          <TimespanDropdown />
        </SplitItem>
        <SplitItem>
          <PollIntervalDropdown />
        </SplitItem>
      </Split>
    </ListPageHeader>
  );
});

HeaderTop.displayName = 'HeaderTop';

type MonitoringDashboardsLegacyPageProps = PropsWithChildren<{
  boardItems: CombinedDashboardMetadata[];
  changeBoard: (params: { newBoard?: string; initialLoad?: boolean; newProject?: string }) => void;
  dashboardName: string;
}>;

export const DashboardSkeletonLegacy = memo(
  ({ children, boardItems, changeBoard, dashboardName }: MonitoringDashboardsLegacyPageProps) => {
    const { t } = useTranslation(process.env.I18N_NAMESPACE);

    const onChangeBoard = useCallback(
      (selectedDashboard: string) => {
        changeBoard({ newBoard: selectedDashboard });
      },
      [changeBoard],
    );

    return (
      <>
        <DocumentTitle>{t('Metrics dashboards')}</DocumentTitle>
        <HeaderTop />
        <PageSection hasBodyWrapper={false}>
          <Stack hasGutter>
            {!_.isEmpty(boardItems) && (
              <StackItem>
                <DashboardDropdown
                  items={boardItems}
                  onChange={onChangeBoard}
                  selectedKey={dashboardName}
                />
              </StackItem>
            )}

            <StackItem>
              <LegacyDashboardsAllVariableDropdowns
                key={dashboardName}
                dashboardName={dashboardName}
              />
            </StackItem>
            <StackItem>
              <Split>
                <SplitItem isFilled />
              </Split>
            </StackItem>
          </Stack>
        </PageSection>
        <Divider />
        {children}
      </>
    );
  },
);

DashboardSkeletonLegacy.displayName = 'DashboardSkeletonLegacy';
